import { defineConfig } from '@tanstack/start/config'
import viteTsconfigPaths from 'vite-tsconfig-paths'

export default defineConfig({
  vite: {
    plugins: [viteTsconfigPaths()],
  },
  server: {
    preset: 'node-server',
  },
})

import { createRouter as createTanStackRouter } from '@tanstack/react-router'
import { routeTree } from './routeTree.gen'

export function createRouter() {
  return createTanStackRouter({
    routeTree,
    scrollRestoration: true,
  })
}

declare module '@tanstack/react-router' {
  interface Register {
    router: ReturnType<typeof createRouter>
  }
}

import { createStartHandler, defaultStreamHandler } from '@tanstack/start/server'
import { createRouter } from './router'

export default createStartHandler({
  createRouter,
})(defaultStreamHandler)

import Database from 'better-sqlite3'
import path from 'path'

const DB_PATH = path.resolve('/home/user/blog/blog.db')

let db: Database.Database | null = null

export function getDb(): Database.Database {
  if (!db) {
    db = new Database(DB_PATH)
    db.pragma('journal_mode = WAL')
    initDb(db)
  }
  return db
}

function initDb(db: Database.Database) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS posts (
      id INTEGER PRIMARY KEY,
      title TEXT NOT NULL,
      content TEXT NOT NULL
    )
  `)

  const count = (db.prepare('SELECT COUNT(*) as count FROM posts').get() as { count: number }).count
  if (count === 0) {
    const insert = db.prepare('INSERT INTO posts (title, content) VALUES (?, ?)')
    insert.run(
      'Welcome to My Blog',
      `# Welcome to My Blog\n\nThis is the **first post** on my blog.\n\n## What to Expect\n\nI'll be writing about:\n\n- Technology\n- Programming\n- Open Source\n\n> Stay tuned for more content!\n\nHere is some \`inline code\` and a code block:\n\n\`\`\`js\nconsole.log("Hello, World!");\n\`\`\`\n`
    )
    insert.run(
      'Getting Started with TanStack Start',
      `# Getting Started with TanStack Start\n\nTanStack Start is a **full-stack React framework** powered by TanStack Router.\n\n## Features\n\n1. File-based routing\n2. Server functions\n3. Full-stack type safety\n\n### Installation\n\n\`\`\`bash\nnpm create tanstack@latest\n\`\`\`\n\nLearn more at the [official docs](https://tanstack.com/start).\n`
    )
  }
}

import { createServerFn } from '@tanstack/start'
import { getDb } from '../db'

export type Post = {
  id: number
  title: string
  content: string
}

export const fetchPosts = createServerFn({ method: 'GET' }).handler(async () => {
  const db = getDb()
  const posts = db.prepare('SELECT id, title, content FROM posts ORDER BY id ASC').all() as Post[]
  return posts
})

export const fetchPost = createServerFn({ method: 'GET' })
  .validator((data: { postId: number }) => data)
  .handler(async ({ data }) => {
    const db = getDb()
    const post = db.prepare('SELECT id, title, content FROM posts WHERE id = ?').get(data.postId) as Post | undefined
    if (!post) {
      throw new Error(`Post with id ${data.postId} not found`)
    }
    return post
  })

import { createRootRoute, Outlet, ScrollRestoration } from '@tanstack/react-router'
import { Meta, Scripts } from '@tanstack/start'
import type { ReactNode } from 'react'

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: 'utf-8' },
      { name: 'viewport', content: 'width=device-width, initial-scale=1' },
      { title: 'My Blog' },
    ],
    links: [],
  }),
  component: RootComponent,
})

function RootComponent() {
  return (
    <RootDocument>
      <Outlet />
    </RootDocument>
  )
}

function RootDocument({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <head>
        <Meta />
        <style>{`
          * { box-sizing: border-box; margin: 0; padding: 0; }
          body { font-family: system-ui, sans-serif; line-height: 1.6; color: #333; background: #f9f9f9; }
          a { color: #0070f3; text-decoration: none; }
          a:hover { text-decoration: underline; }
          .container { max-width: 800px; margin: 0 auto; padding: 2rem 1rem; }
          header { background: #fff; border-bottom: 1px solid #eee; padding: 1rem 0; margin-bottom: 2rem; }
          header .container { padding-top: 0.5rem; padding-bottom: 0.5rem; }
          header h1 { font-size: 1.5rem; }
          .post-list { list-style: none; }
          .post-list li { background: #fff; border: 1px solid #eee; border-radius: 8px; padding: 1.25rem 1.5rem; margin-bottom: 1rem; }
          .post-list h2 { font-size: 1.2rem; margin-bottom: 0.25rem; }
          .post-content h1 { font-size: 2rem; margin: 1.5rem 0 0.75rem; }
          .post-content h2 { font-size: 1.5rem; margin: 1.25rem 0 0.5rem; }
          .post-content h3 { font-size: 1.2rem; margin: 1rem 0 0.5rem; }
          .post-content p { margin-bottom: 1rem; }
          .post-content ul, .post-content ol { margin: 0.5rem 0 1rem 1.5rem; }
          .post-content li { margin-bottom: 0.25rem; }
          .post-content blockquote { border-left: 4px solid #0070f3; padding-left: 1rem; color: #555; margin: 1rem 0; }
          .post-content code { background: #f0f0f0; padding: 0.1em 0.3em; border-radius: 3px; font-size: 0.9em; }
          .post-content pre { background: #1e1e1e; color: #d4d4d4; padding: 1rem; border-radius: 8px; overflow-x: auto; margin-bottom: 1rem; }
          .post-content pre code { background: none; padding: 0; }
          .back-link { display: inline-block; margin-bottom: 1.5rem; }
        `}</style>
      </head>
      <body>
        <header>
          <div className="container">
            <h1><a href="/">My Blog</a></h1>
          </div>
        </header>
        {children}
        <ScrollRestoration />
        <Scripts />
      </body>
    </html>
  )
}

import { createFileRoute, Link } from '@tanstack/react-router'
import { fetchPosts } from '../functions/posts'

export const Route = createFileRoute('/')({
  loader: () => fetchPosts(),
  component: HomeComponent,
})

function HomeComponent() {
  const posts = Route.useLoaderData()

  return (
    <div className="container">
      <h2 style={{ marginBottom: '1.5rem', fontSize: '1.4rem' }}>All Posts</h2>
      {posts.length === 0 ? (
        <p>No posts yet.</p>
      ) : (
        <ul className="post-list">
          {posts.map((post) => (
            <li key={post.id}>
              <h2>
                <Link to="/posts/$postId" params={{ postId: String(post.id) }}>
                  {post.title}
                </Link>
              </h2>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

import { createFileRoute, Link, notFound } from '@tanstack/react-router'
import { fetchPost } from '../functions/posts'
import { marked } from 'marked'

export const Route = createFileRoute('/posts/$postId')({
  loader: async ({ params }) => {
    try {
      const post = await fetchPost({ data: { postId: Number(params.postId) } })
      return post
    } catch {
      throw notFound()
    }
  },
  notFoundComponent: () => (
    <div className="container">
      <p>Post not found.</p>
      <Link to="/" className="back-link">← Back to all posts</Link>
    </div>
  ),
  component: PostComponent,
})

function PostComponent() {
  const post = Route.useLoaderData()
  const htmlContent = marked(post.content) as string

  return (
    <div className="container">
      <Link to="/" className="back-link">← Back to all posts</Link>
      <article>
        <div
          className="post-content"
          dangerouslySetInnerHTML={{ __html: htmlContent }}
        />
      </article>
    </div>
  )
}

